package nl.yinyang.launcher;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.view.*;
import org.json.*;import org.junit.*;import org.junit.runner.RunWith;
import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.ActivityController;
import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(sdk={28,35})
public class WidgetWorkspaceTest {
 ActivityController<MainActivity> controller;MainActivity a;WidgetWorkspace w;
 @Before public void setup(){controller=Robolectric.buildActivity(MainActivity.class).create().start().resume().visible();a=controller.get();a.prefs.edit().clear().commit();w=a.workspace;w.layout(0,0,1080,1920);a.home.layout(0,0,1080,1920);}
 @After public void finish(){controller.pause().stop().destroy();}
 MotionEvent event(int action,float x,float y){return MotionEvent.obtain(0,SystemClock.uptimeMillis(),action,x,y,0);}
 boolean intercept(int action,float x,float y){MotionEvent e=event(action,x,y);boolean r=w.onInterceptTouchEvent(e);e.recycle();return r;}
 void release(float x,float y){MotionEvent e=event(1,x,y);w.onTouchEvent(e);e.recycle();}
 @Test public void swipePhotoAreasOpensBothSidesAndBackReturnsHome(){assertFalse(intercept(0,900,100));assertTrue(intercept(2,400,105));release(100,105);assertEquals(2,w.current);a.onBackPressed();assertEquals(1,w.current);intercept(0,100,100);assertTrue(intercept(2,600,102));release(900,102);assertEquals(0,w.current);}
 @Test public void circleGestureStaysWithCarousel(){float y=a.home.centerY()-a.home.ringRadius();intercept(0,540,y);assertFalse(intercept(2,100,960));assertEquals(1,w.current);}
 @Test public void verticalWidgetScrollDoesNotTurnPage(){w.showPage(0,false);intercept(0,400,800);assertFalse(intercept(2,405,400));assertFalse(intercept(2,800,390));assertEquals(0,w.current);}
 @Test public void canceledPageSwipeDoesNotChangePage(){intercept(0,900,100);assertTrue(intercept(2,300,100));w.onTouchEvent(event(3,300,100));assertEquals(1,w.current);}
 @Test public void photoCardsKeepOrderHeightAndPageAfterRecreation() throws Exception {JSONArray entries=new JSONArray();entries.put(new JSONObject().put("uri","content://photos/one").put("label","Rooster").put("height",400));entries.put(new JSONObject().put("uri","content://photos/two").put("label","Gezin").put("height",240));w.save(0,entries);w.move(0,1,-1);controller.recreate();a=controller.get();w=a.workspace;assertEquals("Gezin",w.entries(0).getJSONObject(0).getString("label"));assertEquals(400,w.entries(0).getJSONObject(1).getInt("height"));assertEquals(0,w.entries(2).length());w.remove(0,0);assertEquals("Rooster",w.entries(0).getJSONObject(0).getString("label"));}
 @Test public void bindingCancellationReleasesAllocatedIdAndPreservesExistingLayout(){int id=w.host.allocateAppWidgetId();a.prefs.edit().putInt("pending_widget",id).putInt("pending_widget_side",2).putString(a.key(0,1),"keep/app").commit();w.result(WidgetWorkspace.BIND,Activity.RESULT_CANCELED,null);assertEquals(-1,a.prefs.getInt("pending_widget",-1));assertEquals(0,w.entries(2).length());assertEquals("keep/app",a.prefs.getString(a.key(0,1),""));}
 @Test public void pendingConfigurationSurvivesRecreationAndCancellation(){int id=w.host.allocateAppWidgetId();a.prefs.edit().putInt("pending_widget",id).putInt("pending_widget_side",2).commit();controller.recreate();a=controller.get();w=a.workspace;assertEquals(id,a.prefs.getInt("pending_widget",-1));w.result(WidgetWorkspace.CONFIGURE,Activity.RESULT_CANCELED,null);assertFalse(a.prefs.contains("pending_widget"));}
 @Test public void addingPhotoUsesDocumentPickerAndKeepsTargetSide(){w.pickPhoto(2);Intent intent=shadowOf(a).getNextStartedActivity();assertEquals(Intent.ACTION_OPEN_DOCUMENT,intent.getAction());assertEquals("image/*",intent.getType());assertEquals(2,a.prefs.getInt("pending_photo_side",-1));w.result(WidgetWorkspace.PHOTO,Activity.RESULT_CANCELED,null);assertFalse(a.prefs.contains("pending_photo_side"));assertEquals(0,w.entries(2).length());}
 @Test public void returningHomeDoesNotResetWheelOrBindings(){a.home.wheelPosition=18;a.prefs.edit().putString(a.key(2,3),"keep/other").commit();w.showPage(2,false);a.onBackPressed();assertEquals(1,w.current);assertEquals(18,a.home.wheelPosition,0);assertEquals("keep/other",a.prefs.getString(a.key(2,3),""));}
 @Test public void pageBoundariesDoNotWrap(){w.showPage(0,false);intercept(0,100,100);intercept(2,700,100);release(1000,100);assertEquals(0,w.current);w.showPage(2,false);intercept(0,900,100);intercept(2,300,100);release(100,100);assertEquals(2,w.current);}
 static class Provider extends AppWidgetProviderInfo {Provider(){provider=new ComponentName("example.widgets","Clock");minHeight=120;label="Klok";android.content.pm.ActivityInfo receiver=new android.content.pm.ActivityInfo();receiver.packageName="example.widgets";receiver.name="Clock";receiver.nonLocalizedLabel="Klok";receiver.applicationInfo=new android.content.pm.ApplicationInfo();receiver.applicationInfo.packageName="example.widgets";receiver.applicationInfo.uid=10000;org.robolectric.util.ReflectionHelpers.setField(this,"providerInfo",receiver);}}
 @Test public void approvedWidgetIsStoredOnChosenPageAndRestored() throws Exception {Provider info=new Provider();shadowOf(w.manager).addInstalledProvider(info);shadowOf(w.manager).setAllowedToBindAppWidgets(true);w.beginWidget(2,info);assertEquals(1,w.entries(2).length());int id=w.entries(2).getJSONObject(0).getInt("id");assertFalse(a.prefs.contains("pending_widget"));assertEquals(2,w.current);controller.recreate();a=controller.get();w=a.workspace;assertEquals(id,w.entries(2).getJSONObject(0).getInt("id"));w.remove(2,0);assertEquals(0,w.entries(2).length());}
 @Test public void widgetPermissionIsRequestedBeforeAdding() {Provider info=new Provider();shadowOf(w.manager).addInstalledProvider(info);shadowOf(w.manager).setAllowedToBindAppWidgets(false);w.beginWidget(0,info);Intent bind=shadowOf(a).getNextStartedActivity();assertEquals(AppWidgetManager.ACTION_APPWIDGET_BIND,bind.getAction());assertEquals(0,w.entries(0).length());w.result(WidgetWorkspace.BIND,Activity.RESULT_OK,null);assertEquals(1,w.entries(0).length());}
 @org.robolectric.annotation.GraphicsMode(org.robolectric.annotation.GraphicsMode.Mode.NATIVE)
 @Test public void renderRosterPageAndKeepWholePhotoVisible() throws Exception {
  android.graphics.Bitmap photo=android.graphics.Bitmap.createBitmap(800,500,android.graphics.Bitmap.Config.ARGB_8888);android.graphics.Canvas c=new android.graphics.Canvas(photo);c.drawColor(0xfff0eadc);android.graphics.Paint pen=new android.graphics.Paint(3);pen.setColor(0xff19283d);pen.setTextSize(46);c.drawText("WERKROOSTER",44,72,pen);pen.setTextSize(28);String[] rows={"Maandag     08:00 - 17:00","Dinsdag       08:00 - 17:00","Woensdag   Vrij","Donderdag   Vrij","Vrijdag         08:00 - 17:00"};for(int r=0;r<rows.length;r++)c.drawText(rows[r],44,150+r*62,pen);
  java.io.File input=new java.io.File(a.getCacheDir(),"roster.png");try(java.io.FileOutputStream out=new java.io.FileOutputStream(input)){photo.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}
  JSONArray values=new JSONArray();values.put(new JSONObject().put("uri",android.net.Uri.fromFile(input).toString()).put("label","Foto / rooster").put("height",400));w.save(0,values);w.showPage(0,false);
  int width=1080,height=1920;a.root.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));a.root.layout(0,0,width,height);
  android.graphics.Bitmap output=android.graphics.Bitmap.createBitmap(width,height,android.graphics.Bitmap.Config.ARGB_8888);a.root.draw(new android.graphics.Canvas(output));java.io.File directory=new java.io.File("build/photo-previews");directory.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(directory,"widgets-"+Build.VERSION.SDK_INT+".png"))){output.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}assertNotNull(w.lists[0].findViewWithTag("widget-edit-0-0"));assertEquals(0,w.current);
 }
}
